#!/bin/bash
# Generated by scripts/sync_firebird_versions.py - idempotent container entrypoint.
set -u

CONF=/opt/firebird/firebird.conf
PW="${SYSDBAPASS:-masterkey}"
FB_PORT="${FIREBIRD_PORT:-3050}"
AUX_PORT="${REMOTE_AUX_PORT:-3051}"

set_conf() {
    # keep firebird.conf free of duplicates across container restarts
    local key="$1" value="$2"
    grep -Eq "^[[:space:]]*${key}[[:space:]]*=" "$CONF" \
        && sed -i -E "s|^[[:space:]]*${key}[[:space:]]*=.*|${key} = ${value}|" "$CONF" \
        || echo "${key} = ${value}" >> "$CONF"
}

set_conf RemoteServicePort "$FB_PORT"
set_conf RemoteAuxPort "$AUX_PORT"

# set/refresh the SYSDBA password (gsec exists up to Firebird 5, isql from 6 on)
if [ -x /opt/firebird/bin/gsec ]; then
    /opt/firebird/bin/gsec -user SYSDBA -password "${OLD_SYSDBAPASS:-masterkey}" \
        -modify SYSDBA -pw "$PW" \
        || echo "WARN: could not update SYSDBA password (already changed?)" >&2
else
    echo "ALTER USER SYSDBA SET PASSWORD '$PW';" \
        | /opt/firebird/bin/isql -user SYSDBA -password "${OLD_SYSDBAPASS:-masterkey}" \
        || echo "WARN: could not update SYSDBA password (already changed?)" >&2
fi

exec /opt/firebird/bin/fbguard -forever
